DO $$ BEGIN CREATE TYPE membership_role AS ENUM ('headman','deputy','student'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE lesson_type AS ENUM ('lecture','practice','laboratory'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE attendance_status AS ENUM ('present','absent','late','excused'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE period_system AS ENUM ('semester','trimester','quarter','year'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS profiles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), auth_user_id text NOT NULL UNIQUE, email text NOT NULL UNIQUE, display_name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS groups (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, description text, period_system period_system NOT NULL, active_period_id uuid, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS academic_periods (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), group_id uuid NOT NULL REFERENCES groups(id), period_number integer NOT NULL, starts_on date NOT NULL, ends_on date NOT NULL, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT period_dates_check CHECK (ends_on >= starts_on), CONSTRAINT period_number_positive CHECK (period_number > 0));
ALTER TABLE groups DROP CONSTRAINT IF EXISTS groups_active_period_id_academic_periods_id_fk;
ALTER TABLE groups ADD CONSTRAINT groups_active_period_id_academic_periods_id_fk FOREIGN KEY (active_period_id) REFERENCES academic_periods(id);
CREATE TABLE IF NOT EXISTS memberships (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), group_id uuid NOT NULL REFERENCES groups(id), profile_id uuid NOT NULL REFERENCES profiles(id), role membership_role NOT NULL, display_name text NOT NULL, is_active boolean NOT NULL DEFAULT true, joined_at date NOT NULL DEFAULT CURRENT_DATE, deactivated_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(group_id, profile_id));
CREATE TABLE IF NOT EXISTS subjects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), group_id uuid NOT NULL REFERENCES groups(id), academic_period_id uuid NOT NULL REFERENCES academic_periods(id), name text NOT NULL, short_name text NOT NULL, teacher text, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS lessons (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), group_id uuid NOT NULL REFERENCES groups(id), academic_period_id uuid NOT NULL REFERENCES academic_periods(id), subject_id uuid NOT NULL REFERENCES subjects(id), lesson_date date NOT NULL, type lesson_type NOT NULL, comment text, created_by_membership_id uuid NOT NULL REFERENCES memberships(id), updated_by_membership_id uuid NOT NULL REFERENCES memberships(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS attendance (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lesson_id uuid NOT NULL REFERENCES lessons(id), student_membership_id uuid NOT NULL REFERENCES memberships(id), status attendance_status NOT NULL, comment text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(lesson_id, student_membership_id));
CREATE TABLE IF NOT EXISTS audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), group_id uuid NOT NULL REFERENCES groups(id), actor_membership_id uuid NOT NULL REFERENCES memberships(id), entity_type text NOT NULL, entity_id uuid NOT NULL, action text NOT NULL, before_data jsonb, after_data jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS groups_active_idx ON groups(is_active);
CREATE INDEX IF NOT EXISTS periods_group_idx ON academic_periods(group_id);
CREATE INDEX IF NOT EXISTS periods_active_idx ON academic_periods(is_active);
CREATE INDEX IF NOT EXISTS memberships_group_idx ON memberships(group_id);
CREATE INDEX IF NOT EXISTS memberships_active_idx ON memberships(is_active);
CREATE INDEX IF NOT EXISTS subjects_group_idx ON subjects(group_id);
CREATE INDEX IF NOT EXISTS subjects_period_idx ON subjects(academic_period_id);
CREATE INDEX IF NOT EXISTS subjects_active_idx ON subjects(is_active);
CREATE INDEX IF NOT EXISTS lessons_group_date_idx ON lessons(group_id, lesson_date DESC);
CREATE INDEX IF NOT EXISTS lessons_period_idx ON lessons(academic_period_id);
CREATE INDEX IF NOT EXISTS lessons_subject_idx ON lessons(subject_id);
CREATE INDEX IF NOT EXISTS attendance_lesson_idx ON attendance(lesson_id);
CREATE INDEX IF NOT EXISTS attendance_student_idx ON attendance(student_membership_id);
CREATE INDEX IF NOT EXISTS attendance_status_idx ON attendance(status);
CREATE INDEX IF NOT EXISTS audit_group_created_idx ON audit_logs(group_id, created_at DESC);
CREATE INDEX IF NOT EXISTS audit_entity_idx ON audit_logs(entity_type, entity_id);
